/**
 * SteeringBehavior - Path following and local obstacle avoidance
 *
 * Path following and local obstacle avoidance using BVH raycasts.
 * Implements arrival slowdown and perpendicular steering for obstacles.
 * Uses BVH raycasts for obstacle detection without path replanning.
 * Steers perpendicular to detected obstacles for smooth avoidance.
 *
 * **Usage**
 *
 * ```js
 * const steering = new SteeringBehavior({ maxSpeed: 5 });
 * const result = steering.calculate(position, velocity, rotation, path, pathIndex, delta);
 * // result.steering - force to apply
 * // result.nextIndex - updated path index
 * // result.arrived - true if reached destination
 * ```
 *
 * @class SteeringBehavior
 * @short Path following and obstacle avoidance
 * @category Core
 * @tags Steering, Avoidance, Path Following, BVH
 */
export class SteeringBehavior {
    /**
     * Create steering behavior.
     *
     * @param {Object} [config] - Configuration options.
     * @param {number} [config.maxSpeed=5.0] - Maximum movement speed.
     * @param {number} [config.maxForce=10.0] - Maximum steering force.
     * @param {number} [config.arrivalRadius=0.8] - Distance to consider arrived at waypoint.
     * @param {number} [config.slowdownRadius=4.0] - Distance to start slowing down.
     * @param {number} [config.avoidanceRadius=1.5] - Obstacle detection radius.
     * @param {number} [config.lookAheadDistance=3.0] - Raycast distance for avoidance.
     * @param {number} [config.separationRadius=2.0] - Distance at which agents push apart.
     * @param {number} [config.separationForce=5.0] - Strength of agent separation.
     */
    constructor(config?: {
        maxSpeed?: number;
        maxForce?: number;
        arrivalRadius?: number;
        slowdownRadius?: number;
        avoidanceRadius?: number;
        lookAheadDistance?: number;
        separationRadius?: number;
        separationForce?: number;
    });
    maxSpeed: number;
    maxForce: number;
    arrivalRadius: number;
    slowdownRadius: number;
    avoidanceRadius: number;
    lookAheadDistance: number;
    separationRadius: number;
    separationForce: number;
    _desired: any;
    _steering: any;
    _avoidance: any;
    _separation: any;
    _rayDir: any;
    _rayOrigin: any;
    _perpendicular: any;
    _losTarget: any;
    _raycaster: any;
    _avoidanceRays: any[];
    /**
     * Configure steering parameters.
     *
     * @param {Object} config - Configuration object.
     * @returns {SteeringBehavior} This instance for chaining.
     */
    set(config: any): SteeringBehavior;
    /**
     * Calculate steering force for path following with avoidance.
     *
     * @param {THREE.Vector3} position - Current agent position.
     * @param {THREE.Vector3} velocity - Current agent velocity.
     * @param {THREE.Quaternion} rotation - Current agent rotation.
     * @param {Array<{x: number, y: number, z: number}>} path - Path waypoints.
     * @param {number} pathIndex - Current waypoint index.
     * @param {number} delta - Time delta in seconds.
     * @returns {{ steering: THREE.Vector3, nextIndex: number, arrived: boolean }}
     */
    calculate(position: THREE.Vector3, velocity: THREE.Vector3, rotation: THREE.Quaternion, path: Array<{
        x: number;
        y: number;
        z: number;
    }>, pathIndex: number, delta: number): {
        steering: THREE.Vector3;
        nextIndex: number;
        arrived: boolean;
    };
    /**
     * Calculate avoidance force using BVH raycasts.
     *
     * @param {THREE.Vector3} position - Agent position.
     * @param {THREE.Quaternion} rotation - Agent rotation.
     * @private
     */
    private _calculateAvoidance;
    /**
     * Get distance to final destination.
     *
     * @param {THREE.Vector3} position - Current position.
     * @param {Array} path - Path waypoints.
     * @returns {number} Distance to final waypoint.
     */
    getDistanceToGoal(position: THREE.Vector3, path: any[]): number;
    /**
     * Check if there's a clear line-of-sight to a waypoint.
     * Used to prevent corner-cutting through walls.
     *
     * @param {THREE.Vector3} position - Agent position.
     * @param {{x: number, y: number, z: number}} waypoint - Target waypoint.
     * @returns {boolean} True if waypoint is visible (no obstacles).
     * @private
     */
    private _hasLineOfSight;
}
